begin;
set local search_path=public,extensions;
select no_plan();
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"20000000-0000-4000-8000-000000000003","role":"authenticated","aal":"aal1"}',true);
select is((select (metric->>'value')::numeric from public.impact_metrics_cohort('2026-01-01','2026-12-31',null,null,null,'absent-product') metric where metric->>'id'='KPI-01'),0::numeric,'An absent product cohort has no source whey mass');
select is((select (metric->>'value')::numeric from public.impact_metrics_cohort('2026-01-01','2026-12-31',null,null,null,null) metric where metric->>'id'='KPI-01'),(select (metric->>'value')::numeric from public.impact_metrics_filtered('2026-01-01','2026-12-31',null,null) metric where metric->>'id'='KPI-01'),'Unfiltered cohort metrics preserve the formal calculation');
select is(public.operational_dashboard('2026-01-01','2026-12-31',null,null,null,'absent-product')->'monthly','[]'::jsonb,'Product filter also applies to operational monthly activity');
select throws_ok($$select public.participation_demographics('10000000-0000-4000-8000-000000000002',null)$$,'P0001','Cooperative outside dashboard scope','Demographic aggregates remain within manager scope');
select throws_ok($$select public.record_client_diagnostic(gen_random_uuid(),'30000000-0000-4000-8000-000000000001','client_error','home',now())$$,'P0001','Registered active device required','Diagnostic cannot impersonate another user device');
select set_config('request.jwt.claims','{"sub":"20000000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal1"}',true);
select public.record_consent('female','25-34',true);
select set_config('request.jwt.claims','{"sub":"20000000-0000-4000-8000-000000000003","role":"authenticated","aal":"aal1"}',true);
select is(jsonb_array_length(public.participation_demographics(null,null)),2,'Consenting profile contributes only to its two grouped dimensions');
select ok((select bool_and((value->>'suppressed')::boolean and value->'value'='null'::jsonb) from jsonb_array_elements(public.participation_demographics(null,null))),'Small demographic groups never disclose their counts');
select set_config('request.jwt.claims','{"sub":"20000000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal1"}',true);
select public.record_consent('female','25-34',false);
select set_config('request.jwt.claims','{"sub":"20000000-0000-4000-8000-000000000003","role":"authenticated","aal":"aal1"}',true);
select is(public.participation_demographics(null,null),'[]'::jsonb,'Consent withdrawal excludes the demographic profile immediately');
select set_config('request.jwt.claims','{"sub":"20000000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal1"}',true);
select lives_ok($$select public.record_client_diagnostic(gen_random_uuid(),'30000000-0000-4000-8000-000000000001','sync_failure','batches',now())$$,'Sanitized diagnostic from the registered device is retained');
select is((select count(*) from public.client_diagnostic),0::bigint,'Producer cannot read diagnostic rows');
select throws_ok($$select public.record_client_diagnostic(gen_random_uuid(),'30000000-0000-4000-8000-000000000001','client_error','private-customer-name',now())$$,'P0001','Invalid diagnostic context','Diagnostic route is constrained to screen identifiers');
select set_config('request.jwt.claims','{"sub":"20000000-0000-4000-8000-000000000004","role":"authenticated","aal":"aal2"}',true);
select throws_ok($$select public.draft_scoped_configuration('kpi','{"metrics":[]}',now(),null)$$,'P0001','Global dictionary requires the thirteen formal metrics','Incomplete formal dictionary is not accepted');
select lives_ok($$select public.draft_scoped_configuration('kpi',(select jsonb_build_object('metrics',jsonb_agg(to_jsonb(k)||jsonb_build_object('definition',k.definition||' Approved clarification'))) from public.kpi_definition k),now(),null)$$,'Complete metric definition clarifications can be drafted');
select throws_ok($$select public.draft_scoped_configuration('kpi',(select jsonb_build_object('metrics',jsonb_agg(to_jsonb(k)||'{"calculation":"arbitrary formula"}'::jsonb)) from public.kpi_definition k),now(),null)$$,'P0001','Metric calculations and access rules require a code-reviewed methodology change','A dictionary edit cannot mislabel the authoritative formula');
select throws_ok($$select public.draft_scoped_configuration('sop',(select definition||'{"data_quality_rules":{"negative_quantities":"warning"}}'::jsonb from public.config_version where id='40000000-0000-4000-8000-000000000001'),now(),null)$$,'P0001','Unsupported configurable rule; physical and safety invariants always block','Configuration cannot downgrade always-blocking invariants');
select lives_ok($$select public.draft_scoped_configuration('sop',(select definition||'{"units":["kg","unit"],"ingredient_types":["Bulgur","Salt"],"data_quality_rules":{"overdue_calibration":"blocking"}}'::jsonb from public.config_version where id='40000000-0000-4000-8000-000000000001'),now(),null)$$,'Approved catalogs and configurable process controls can be drafted');
select set_config('request.jwt.claims','{"sub":"20000000-0000-4000-8000-000000000007","role":"authenticated","aal":"aal1"}',true);
select ok((select bool_and((metric->>'suppressed')::boolean) from public.impact_metrics_cohort('2026-01-01','2026-12-31',null,null,'released','absent-product') metric),'Filtered donor groups remain suppressed');
reset role;
create temporary table consenting_five(user_id uuid);
insert into consenting_five select gen_random_uuid() from generate_series(1,5);
insert into wise_auth.users(id,email) select user_id,user_id::text||'@example.invalid' from consenting_five;
insert into public.membership(user_id,cooperative_id,username,display_name,roles) select user_id,'10000000-0000-4000-8000-000000000001','fixture_'||substr(replace(user_id::text,'-',''),1,12),'Consent test',array['producer'] from consenting_five;
insert into public.producer_profile(user_id,cooperative_id,sex,age_band,consent_at) select user_id,'10000000-0000-4000-8000-000000000001','female','25-34',now() from consenting_five;
set local role authenticated;
select ok((select bool_and(not (value->>'suppressed')::boolean and (value->>'value')::integer=5) from jsonb_array_elements(public.participation_demographics('10000000-0000-4000-8000-000000000001',null))),'Groups at the five-person boundary display the aggregate count');
select * from finish();rollback;
